// ---------------------------------------------------------------- helpers
function collectGaps(manifest, out) {
    const visit = (el) => {
        if (el.gap)
            out.add(el.gap);
        for (const c of el.children ?? [])
            visit(c);
    };
    for (const s of manifest.screens) {
        for (const v of s.variants)
            visit(v.tree);
    }
}
function collectTreeTextNodes(tree) {
    const out = [];
    const visit = (el) => {
        if (el.role === "text")
            out.push(el);
        for (const t of el.text_slots ?? []) {
            out.push({ id: el.id, role: "text", name: el.name, text: t });
        }
        for (const c of el.children ?? [])
            visit(c);
    };
    visit(tree);
    return out;
}
function collectTreeVectorNodes(tree) {
    const out = [];
    const visit = (el) => {
        if (el.role === "vector")
            out.push(el);
        for (const c of el.children ?? [])
            visit(c);
    };
    visit(tree);
    return out;
}
function phpString(v) {
    return v.replaceAll("\\", "\\\\").replaceAll("'", "\\'");
}
function indentBlock(text, indent) {
    return text
        .split("\n")
        .map((l) => (l.length > 0 ? `${indent}${l}` : l))
        .join("\n");
}
function round2(v) {
    return Math.round(v * 100) / 100;
}
function treeContainsId(tree, ids) {
    if (ids.has(tree.id))
        return true;
    return (tree.children ?? []).some((c) => treeContainsId(c, ids));
}
